(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.9"]={"from":216,"a":[["\u0003וסתרתה למזיה\u0004 \u0005[ופרעה את שערותיה]\u0006 כמתרחצת. \u0003כל דאתא חזיה הדר, אדהכי והכי אבלעו\u0004 \u0005[\u0006מי \u0005שבא ראה אותה\u0006 ו\u0005חזר\u0006 לאחוריו, \u0005ובין כך וכך נבלעו\u0006 להם אנשי קרח\u0005],\u0006 וניצל און בן פלת.","\u0003איתתיה\u0004 \u0005[אשתו]\u0006 של \u0003קרח אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003חזי מאי קעביד\u0004 \u0005[ראה מה שעושה]\u0006 \u0003משה,\u0004 \u0003איהו\u0004 \u0005[הוא]\u0006 — \u0003הוה מלכא\u0004 \u0005[הריהו מלך],\u0006 \u0003לאחוה\u0004 \u0005[את אחיו]\u0006 \u0003שוויה כהנא רבא\u0004 \u0005[עשה כהן גדול],\u0006 \u0003לבני אחוהי\u0004 \u0005[את בני אחיו]\u0006 \u0003—\u0004 \u0003שוינהו סגני דכהנא\u0004 \u0005[עשה סגני כהונה],\u0006 \u0003אי אתיא\u0004 \u0005[אם באה]\u0006 \u0003תרומה, אמר: תיהוי\u0004 \u0005[אומר\u0006 הוא ש\u0005תהיה]\u0006 \u0003לכהן, אי אתו\u0004 \u0005[אם בא]\u0006 \u0003מעשר\u0004 ראשון \u0003דשקילתו אתון\u0004 \u0005[שמקבלים אתם],\u0006 \u0003אמר\u0004 \u0005[\u0006הריהו \u0005אומר]:\u0006 \u0003הבו חד\u0004 \u0005[תנו אחד]\u0006 \u0003מעשרה לכהן.\u0004 \u0003ועוד, דגייז ליה למזייכו, ומיטלל לכו כי כופתא, עינא יהב במזייכו\u0004 \u0005[שגזז את שערותיכם ומגלגל אתכם כמו רעי,\u0006 כאילו \u0005עין נתן בשערותיכם],\u0006 ורוצה שתהיו מגולחים ולא יפים. \u0003אמר לה\u0004 קרח: \u0003הא איהו נמי קא עביד\u0004 \u0005[הרי הוא גם כן עושה\u0006 כך\u0005],\u0006 שגילח את כל שערו כשאר הלויים. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003כיון דכולהו רבותא דידיה\u0004 \u0005[שכולם\u0006 ל\u0005גדולתו שלו],\u0006 \u0003אמר איהו נמי\u0004 \u0005[הוא גם כן]\u0006 בבחינת \u0003\"תמת נפשי עם פלשתים\"\u0004 (שופטים טז, ל), ואינו נפגע כל כך,","\u0003ועוד\u0004 אמרה לו: \u0003דקאמר לכו עבדיתו תכלתא\u0004 \u0005[שאמר לכם עשו תכלת\u0006 בציצית\u0005],\u0006 \u0003אי סלקא דעתך תכלתא חשיבא\u0004 \u0005[אם עולה על דעתך,\u0006 סבור אתה משה כי \u0005תכלת]\u0006 חשובה ל\u0003מצוה\u0004 — \u0003אפיק גלימי דתכלתא וכסינהו לכולהו מתיבתך\u0004 \u0005[הוצא גלימות\u0006 שכולן \u0005תכלת, וכסה את כל\u0006 בני \u0005ישיבתך]\u0006 בגלימות תכלת בלא ציציות ומדוע לא ייחשבו אלה למצוה? אלא בוודאי בודה הוא כל זה מלבו. \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"חכמות נשים בנתה ביתה\"\u0004 (משלי יד, א) — \u0003זו אשתו של און בן פלת, \"ואולת בידה תהרסנה\"\u0004 (משלי יד, א) — \u0003זו אשתו של קרח.\u0004","נאמר שם: \u0003\"ויקמו לפני משה ואנשים מבני ישראל חמשים ומאתים\"\u0004 (במדבר טז, ב). ומי היו אלה האנשים — \u0003מיוחדים שבעדה\u0004 היו. \u0003\"קראי מועד\"\u0004 — \u0003שהיו יודעים לעבר שנים ולקבוע חדשים,\u0004 שהם היו האנשים הקובעים את המועדים. \u0003\"אנשי שם\"\u0004 — \u0003שהיה להם שם בכל העולם.\u0004","נאמר: \u0003\"וישמע משה ויפל על פניו\"\u0004 (במדבר טז, ד), ושואלים: \u0003מה שמועה שמע\u0004 שהתרגש כל כך? \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: שחשדוהו מאשת איש,\u0004 שהאשימוהו שחוטא באשת איש, ולכך נפגע ביותר, \u0003שנאמר: \"ויקנאו למשה במחנה\"\u0004 (תהלים קו, טז). \u0003אמר ר' שמואל בר יצחק: מלמד שכל אחד ואחד קנא את אשתו ממשה,\u0004 שהזהירה שלא תסתר עמו ביחידות, \u0003שנאמר: \"ומשה יקח את האהל ונטה לו מחוץ למחנה\"\u0004 (שמות לג, ז) שמפני דיבה זו פרש מן המחנה.","על הנאמר \u0003\"ויקם משה וילך אל דתן ואבירם\"\u0004 (במדבר טז, כה), \u0003אמר ריש לקיש: מכאן\u0004 למדנו \u0003שאין מחזיקין במחלוקת,\u0004 שאף הצד הצודק ראוי לו לוותר הרבה ולנסות להתפייס. שהרי דתן ואבירם הם שהאשימו את משה והם שהיו צריכים ללכת לפייסו, ובכל זאת לא עמד משה על דעתו והלך לקראתם. ש\u0003אמר רב: כל המחזיק במחלוקת עובר בלאו\u0004 (מצות \"לא תעשה\"), \u0003שנאמר: \"ולא יהיה כקרח וכעדתו\u0004 כאשר דבר ה' ביד משה לו \u0003\"\u0004(במדבר, יז, ה), שאיסור הוא להיות בעל מחלוקת כמותם.","\u0003רב אשי אמר:\u0004 הממשיך במחלוקת \u0003ראוי ליצטרע,\u0004 ומנין אתה למד זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ביד משה לו\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ויאמר ה' לו עוד הבא נא ידך בחיקך\u0004 ויבא ידו בחיקו ויוציאה והנה ידו מצורעת כשלג \u0003\"\u0004(שמות ד, ו), שמגזירה שווה מהמילים \"לו\" למדים שעונשה של מחלוקת — צרעת.","כיון שהוזכר איסור מחלוקת בכלל מוסיפים בענין זה; \u0003אמר ר' יוסי: כל החולק על מלכות בית דוד ראוי להכישו\u0004 \u0005[לנשכו]\u0006 \u0003נחש.\u0004 ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויזבח אדניהו צאן ובקר ומריא עם אבן הזחלת\"\u0004 (מלכים א' א, ט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"עם חמת זחלי עפר\"\u0004 (דברים לב, כד), משמע ש\"זוחלים\" אלו נחשים הם, ואדוניהו ראוי היה להכשת נחש.","\u0003אמר רב חסדא: כל החולק על רבו\u0004 — \u0003כחולק על השכינה, שנאמר: \"בהצתם על ה' \"\u0004(במדבר כו, ט), ואותו ריב על משה היה, ללמד שהחולק עליו כחולק על השכינה. \u0003אמר ר' חמא בר' חנינא: כל העושה מריבה עם רבו\u0004 הריהו \u0003כעושה\u0004 מריבה \u0003עם שכינה, שנאמר: \"המה מי מריבה אשר רבו בני ישראל את ה' \"\u0004(במדבר כ, יג), אף שמריבתם היתה עם משה.","\u0003אמר ר' חנינא בר פפא: כל המתרעם על רבו\u0004 שעשה לו עוול הריהו \u0003כאילו מתרעם על השכינה, שנאמר: \"לא עלינו תלנתיכם כי על ה' \"\u0004(שמות טז, ח). \u0003אמר ר' אבהו: כל המהרהר\u0004 \u0003אחר רבו\u0004 שטעה או שחטא בדבר מה — \u0003כאילו מהרהר אחר שכינה, שנאמר: \"וידבר העם באלהים ובמשה\"\u0004 (במדבר כא, ה), שעשה הכתוב שניהם כביכול כאחד לענין זה.","על הנאמר \u0003\"עשר שמור לבעליו לרעתו\"\u0004 (קהלת ה, יב), \u0003אמר ריש לקיש: זה עושרו של קרח\u0004 שלא הביא לו תועלת. ומנין שהיה עשיר — שנאמר: \u0003\"ואת כל היקום אשר ברגליהם\"\u0004 (דברים יא, ו), ולפרש כתוב זה \u0003אמר ר' אלעזר:\u0004 \"יקום\" \u0003זה ממונו של אדם, שמעמידו\u0004 (מקימו) \u0003על רגליו. ואמר ר' לוי:\u0004 כדי \u0003משוי\u0004 (משא) \u0003שלש מאות פרדות לבנות היו\u0004 רק ה\u0003מפתחות של בית גנזיו של קרח, וכולהו אקלידי וקילפי דגילדא\u0004 \u0005[וכולם מפתחות וקופסאות של עור],\u0006 ומכאן נבין מה רבים היו האוצרות עצמם.","\u0003אמר ר' חמא בר' חנינא: שלש מטמוניות הטמין יוסף במצרים\u0004 מן הכסף שצבר במכירת התבואה, \u0003אחת\u0004 מהן \u0003נתגלתה לקרח, ואחת נתגלתה לאנטונינוס בן אסוירוס\u0004 קיסר רומי, \u0003ואחת גנוזה לצדיקים לעתיד לבוא\u0004 בימות המשיח (ב\"ש).","\u0003ואמר ר' יוחנן: קרח\u0004 עצמו \u0003לא מן הבלועים\u0004 היה \u0003ולא מן השרופין\u0004 היה, אלא במגפה מת. \u0003לא מן הבלועין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ותפתח הארץ את פיה ותבלע אותם ואת בתיהם \u0003ואת כל האדם אשר לקרח\"\u0004 (במדבר טז, לב), משמע: \u0003ולא קרח\u0004 עצמו בתוכם. \u0003ולא מן השרופים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"באכל האש את חמשים ומאתים איש\"\u0004 (במדבר כו, י), משמע: \u0003ולא קרח\u0004 בתוכם.","ואילו \u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003קרח מן השרופין ומן הבלועין\u0004 היה, ששני העונשים נתקיימו בו. \u0003מן הבלועים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ותפתח הארץ את פיה \u0003ותבלע אתם ואת\u0004 בתיהם ואת כל האדם אשר ל\u0003קרח\"\u0004 (במדבר כו, י), \u0003מן השרופין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ואש יצאה מאת ה' ותאכל את החמשים ומאתים איש\u0004 מקריבי הקטורת\u0003\"\u0004 (במדבר טז, לה), \u0003וקרח בהדייהו\u0004 \u0005[עמם].\u0006","\u0003אמר רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שמש ירח עמד זבלה לאור חציך יהלכו\"\u0004 (חבקוק ג, יא) — \u0003מלמד שעלו שמש וירח לזבול\u0004 שהוא אחד משבעת הרקיעים, ובו מקדש של מעלה, \u0003אמרו לפניו: רבונו של עולם! אם אתה עושה דין לבן עמרם\u0004 ומראה צדקתו -- \u0003נצא\u0004 ונאיר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 תעשה כן — \u0003לא נצא. עד שזרק\u0004 (ה') \u0003בהם חצים. אמר להן: בכבודי לא מחיתם\u0004 אף שאתם רואים בכל יום שעובדים אתכם בעבודה זרה, \u0003בכבוד בשר ודם מחיתם?!\u0004 ומעירים: \u0003והאידנא\u0004 \u0005[ועכשיו]\u0006 הם \u0003לא נפקי\u0004 \u0005[יוצאים]\u0006 להאיר \u0003עד דמחו להו\u0004 \u0005[שמכים אותם],\u0006 שמפני כבוד ה' אינם רוצים לצאת.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ואם בריאה יברא ה' ופצתה האדמה את פיה\"\u0004 (במדבר טז, ל) — \u0003אמר משה לפני הקדוש ברוך הוא: אם בריאה\u0004 (ברואה) כבר \u0003גיהנם\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003יברא ה'\u0004 אותה עכשיו. ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 לאיזה ענין ביקש זאת? \u0003אילימא למבריה\u0004 \u0005[אם תאמר לברוא אותה]\u0006 \u0003ממש, והא\u0004 \u0005[והרי]\u0006 יודעים אנו ש\u0003\"אין כל חדש תחת השמש\"\u0004 (קהלת א, ט), שלא תיתכן בריאת דבר חדש לגמרי לאחר ששת ימי בראשית, \u0003אלא לקרובי פיתחא\u0004 \u0005[לקרב\u0006 את \u0005פתחה]\u0006 של גיהנם לאותו מקום, שייבלעו שם עדת קרח.","על הנאמר \u0003\"ובני קרח לא מתו\"\u0004 (במדבר כו, יא), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003רבינו, אמרו: מקום נתבצר\u0004 (נתחזק ונבדל) \u0003להם בגיהנם וישבו עליו ואמרו שירה. אמר רבה בר בר חנה: זימנא חדא הוה קאזלינא באורחא\u0004 \u0005[פעם אחת הייתי הולך בדרך],\u0006 \u0003אמר לי ההוא טייעא\u0004 \u0005[ערבי אחד]:\u0006 \u0003תא ואחוי\u0004 \u0005[בוא ואראה]\u0006 \u0003לך\u0004 את \u0003בלועי\u0004 מחלוקת \u0003קרח.\u0004 \u0003אזיל חזא תרי בזעי דהוה קא נפק קיטרא מנייהו\u0004 \u0005[הלך\u0006 ו\u0005ראה שני בקעים שיוצא עשן מהם].\u0006 \u0003שקל גבבא דעמרא, אמשייה מיא, ואותביה בריש רומחיה, ואחלפיה התם, איחרך\u0004 \u0005[לקח\u0006 אותו ערבי \u0005גיזת צמר, הרטיבה במים, ושמה בראש רומחו, והעביר אותה שם, ונחרכה]\u0006 להראותו כמה לוהט המקום. \u0003אמר לי: אצית מה שמעת\u0004 \u0005[הקשב מה אתה שומע],\u0006 \u0003ושמעית דהוו קאמרי הכי\u0004 \u0005[ושמעתי\u0006 אותם \u0005שהיו\u0006 \u0005אומרים כך]:\u0006 \u0003\"משה ותורתו אמת, והן\u0004 (עצמם) \u0003בדאים\".\u0004"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 הערבי: \u0003כל תלתין יומין מהדרא להו\u0004 \u0005[שלושים יום מחזירה אותם]\u0006 \u0003גיהנם\u0004 למקום זה \u0003כ\u0004דרך שמתבשל \u0003בשר בתוך קלחת, ואמרי הכי\u0004 \u0005[ואומרים\u0006 הם \u0005כך]:\u0006 \u0003\"משה ותורתו אמת והן בדאים\".\u0004","שנינו במשנה ש\u0003דור המדבר אין להם חלק לעולם הבא.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דור המדבר אין להם חלק לעולם הבא, שנאמר: \"במדבר הזה יתמו ושם ימתו\"\u0004 (במדבר יד, לה) ומפרשים: \u0003\"יתמו\"\u0004 — \u0003בעולם הזה, \"ושם ימתו\"\u0004 — \u0003בעולם הבא. ואמר\u0004 בענין דור המדבר: \u0003\"אשר נשבעתי באפי אם יבאון אל מנוחתי\"\u0004 (תהלים צה, יא), כלומר, שאינם זוכים למנוחת הנצח, אלו \u0003דברי ר' עקיבא.\u0004","\u0003ר' אליעזר אומר: באין הן לעולם הבא, שנאמר: \"אספו לי חסידי כרתי בריתי עלי זבח\"\u0004 (תהלים נ, ה) — אלו יוצאי מצרים שכרתו ברית עולם עם ה' בהר סיני. \u0003אלא מה אני מקיים \"אשר נשבעתי באפי\"?\u0004 יש להבין: \u0003באפי\u0004 (בכעסי) \u0003נשבעתי\u0004 בשעתו, \u0003וחוזרני בי\u0004 כאשר סרה חמת ה' מהם.","\u0003ר' יהושע בן קרחה אומר: לא נאמר פסוק זה\u0004 לדור המדבר \u0003אלא כנגד דורות הבאים,\u0004 וכך יש להבינו: \u0003\"אספו לי חסידי\"\u0004 — \u0003אלו צדיקים שבכל דור ודור, \"כרתי בריתי\"..\u0004 — \u0003אלו חנניה מישאל ועזריה שמסרו עצמן\u0004 על קידוש השם \u0003לתוך כבש האש, \"עלי זבח\"\u0004 — \u0003אלו ר' עקיבא וחביריו, שמסרו עצמן לשחיטה על דברי תורה.\u0004","\u0003ר' שמעון בן מנסיא אומר: באים הן\u0004 דור המדבר \u0003לעולם הבא, שנאמר: \"ופדויי ה' ישבון ובאו ציון ברנה\"\u0004 (ישעיה לה, י), לומר שאותם שפדה ה' פעם — עוד יבואו לציון. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: שבקה\u0004 \u0005[עזב,\u0006 הניח \u0005אותה]\u0006 \u0003ר' עקיבא לחסידותיה\u0004 \u0005[את חסידותו]\u0006 ודרש דברים קשים מאוד. והרי אלו יוצאי מצרים \u0003ש\u0004הרי \u0003נאמר\u0004 עליהם \u0003\"הלך וקראת באזני ירושל ם לאמר\u0004 כה אמר ה' \u0003זכרתי לך חסד נעוריך אהבת כלולתיך לכתך אחרי במדבר בארץ לא זרועה\"\u0004 (ירמיה ב, ב) — \u0003ומה אחרים באים\u0004 לעולם הבא \u0003בזכותם\u0004 של יוצאי מצרים שהלכו אחרי ה' במדבר, \u0003הם עצמן לא כל שכן.\u0004","\u0003עשרת השבטים אינן עתידין לחזור\u0004 עוד לארץ ישראל אף בימות המשיח, \u0003שנאמר: \"וישלכם אל ארץ אחרת כיום הזה\"\u0004 (דברים כט, כז), \u0003מה היום הולך ואינו חוזר\u0004 — \u0003אף הם הולכים ואינן חוזרים,\u0004 אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר: \"כיום הזה\",\u0004 משמעו — \u0003מה יום מאפיל ומאיר\u0004 למחרת — \u0003אף עשרת השבטים שאפילה להן\u0004 בזמנו, \u0003כך עתידה להאיר להם\u0004 לעתיד לבא.","ועוד בענין עשרת השבטים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: בני \u0003עשרת השבטים אין להם חלק לעולם הבא, שנאמר: \"ויתשם ה' מעל אדמתם באף ובחמה ובקצף גדול\u0004 וישליכם אל ארץ אחרת כיום הזה\u0003\"\u0004 (דברים כט, כז, ודורשים: \u0003\"ויתשם ה' מעל אדמתם\"\u0004 — \u0003בעולם הזה, \"וישלכם אל ארץ אחרת\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. ר' שמעון בן יהודה איש כפר עכו אומר משום\u0004 (בשם) \u0003ר' שמעון: אם מעשיהם\u0004 ממשיכים להיות רעים \u0003כיום הזה\u0004 שהם חוטאים — \u0003אינן חוזרין, ואם לאו\u0004 \u0005[לא]\u0006 שישובו בתשובה — \u0003חוזרין.\u0004","\u0003רבי אומר: באים הם\u0004 בני עשרת השבטים \u0003לעולם הבא, שנאמר: \"ביום ההוא יתקע בשופר גדול\u0004 ובאו האובדים בארץ אשור והנדחים בארץ מצרים והשתחוו לה' בהר הקודש בירושלים\u0003\"\u0004 (ישעיה כז, יג). \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 אף כאן \u0003שבקה\u0004 \u0005[עזב,\u0006 הניח \u0005אותה]\u0006 \u0003ר' עקיבא לחסידותיה\u0004 \u0005[את חסידותו]\u0006 ודרש דברים קשים, אף על פי \u0003שנאמר: \"הלך וקראת את הדברים האלה צפונה ואמרת שובה משבה ישראל נאם ה' לוא אפיל פני בכם כי חסיד אני נאם ה' לא אטור לעולם\"\u0004 (ירמיה ג, יב), הרי שניבא הנביא לשיבת עשרת השבטים לארץ.","כיון שהוזכר הדבר שואלים: \u0003מאי חסידותיה\u0004 \u0005[מהי חסידותו]\u0006 של ר' עקיבא שהוזכרה כאן? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטני בני רשעי ישראל,\u0004 כלומר, ילדים קטנים שמתו לרשעי ישראל, שאין להם לא זכות עצמם ולא זכות אבות \u0003אין באין לעולם הבא, שנאמר: \"כי הנה היום בא בער כתנור והיו כל זדים וכל עשה רשעה קש ולהט אתם היום הבא אמר ה' צבאות אשר לא יעזב להם שרש וענף\"\u0004 (מלאכי ג, יט), \"שורש וענף\" משמעו צאצאים, וכך הוא נדרש: לא יעזב להם \u0003\"שרש\"\u0004 משמעו — \u0003בעולם הזה, \"וענף\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי רבן גמליאל.\u0004","\u0003ר' עקיבא אומר: באים הם לעולם הבא, שנאמר: \"שמר פתאים ה'\u0004 דלותי ולי יהושיע\u0003\"\u0004 (תהלים קטז, ו), \u0003שכן קורין בכרכי הים לינוקא\u0004 \u0005[לתינוק]\u0006 \u0003\"פתיא\",\u0004 ואם כן \"פתאים\" הם התינוקות. \u0003ואומר \"גדו אילנא וחבלוהי ברם עקר שרשוהי בארעא שבקו\"\u0004 (דניאל ד, כ) \u0005[קצצו את האילן וחבלוהו, אבל\u0006 את \u0005עיקר שורשיו בארץ הניחו],\u0006 ואם לנבוכדנצר נאמר כך, כל שכן לרשעי ישראל. \u0003אלא מה אני מקיים \"לא יעזב להם שרש וענף\"\u0004 — \u0003שלא יניח להם לא מצוה ולא שיורי מצוה\u0004 שיקבלו עליה שכר. הרי שר' עקיבא מהפך בזכות אלה ומוצא להם תקוה. \u0003דבר אחר: \"שרש\"\u0004 — \u0003זו נשמה, \"וענף\"\u0004 — \u0003זה הגוף,\u0004","\u0003אבל קטני בני רשעי אומות העולם דברי הכל אין באין לעולם הבא,\u0004 שאין להם זכות כלל. \u0003ורבן גמליאל נפקא ליה\u0004 \u0005[יוצא לו\u0006 דבר זה\u0005]\u0006 בקטני רשעי האומות \u0003מ\u0004הכתוב \u0003\"ותאבד כל זכר למו\"\u0004 (ישעיה כו, יד).","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בנושא דומה: \u0003קטן\u0004 (תינוק) שמת \u0003מאימתי\u0004 הוא \u0003בא לעולם הבא? ר' חייא ור' שמעון בר רבי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: משעה שנולד, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: משעה שסיפר\u0004 (דיבר), ומסבירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003משעה שנולד,\u0004 הוא לומד זאת ממה \u0003שנאמר: \"יבאו ויגידו צדקתו לעם נולד כי עשה\"\u0004 (תהלים כב, לב). \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003משעה שסיפר\u0004 (שדיבר), הוא לומד זאת \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זרע יעבדנו יספר לה' לדור\"\u0004 (שם לא), שמשעה שהוא מספר, מאז שייך הוא לה'.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים אחרים באותו ענין, \u0003רבינא אמר: משעה שנזרע\u0004 אף לפני שנולד הוא בא לחיי העולם הבא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זרע יעבדנו\"\u0004 (תהלים כב, לב), משמע שכבר מהיותו זרע בלבד הריהו זוכה לחיי עולם. \u0003ר' נחמן בר יצחק אמר: משעה שנימול, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עני אני וגוע מנער נשאתי אמיך אפונה\"\u0004 (תהלים פח, טז), שמשעה שהוא נושא עליו את סימן הברית מפני מורא ה' (\"אמיך\"), מאז פונה הוא אליו ושייך לו.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' מאיר: משעה שיאמר\u0004 הילד \u0003\"אמן\", שנאמר: \"פתחו שערים ויבא גוי צדיק שמר אמנים\"\u0004 (ישעיה כו, ב), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שמר אמנים\", אלא: \"שאומר אמן\",\u0004 שמשעה זו נפתחים בפניו שערי העולם הבא."],["\u0003מאי\u0004 \u0005[מה]\u0006 עניינה, ושבחה של עניית \u0003\"אמן\"? אמר ר' חנינא:\u0004 \"אמן\" הוא גם ראשי תיבות של \u0003\"אל מלך נאמן\".\u0004","על הנאמר \u0003\"לכן הרחיבה שאול נפשה ופערה פיה לבלי חק\"\u0004 (ישעיה ה, יד), \u0003אמר ריש לקיש:\u0004 \"בלי חוק\" פירושו: \u0003למי שמשייר אפילו חוק אחד\u0004 שלא עשאו — פעורה לו השאול. \u0003אמר ר' יוחנן: לא ניחא למרייהו דאמרת להו הכי\u0004 \u0005[נוח לאדונם,\u0006 ה', \u0005שאומר אתה להם כך],\u0006 שלשיטתו רוב ישראל יורדי גיהנם הם, \u0003אלא\u0004 יש לומר: \u0003אפילו לא למד אלא חוק אחד,\u0004 יש לו חלק לעולם הבא, ו\"לבלי חוק\" פירושו מי שאין לו כל חוק.","על מה \u0003שנאמר\u0004 \u0003\"והיה בכל הארץ נאם ה' פי שנים בה יכרתו יגועו והשלישית יותר בה\"\u0004 (זכריה יג, ח), \u0003אמר ריש לקיש:\u0004 \"שלישית\" זו כוונתה — חלק \u0003שלישי\u0004 מצאצאיו \u0003של שם\u0004 בן נח, שמלבדם ימותו הכל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לריש לקיש: \u0003לא ניחא למרייהו דאמרת להו הכי\u0004 \u0005[נוח לאדונם,\u0006 ה', \u0005שאומר אתה להם כך]\u0006 שישמיד את רוב העולם, \u0003אלא אפילו\u0004 חלק \u0003שלישי של נח,\u0004 ששליש מיושבי העולם ישארו בחיים.","ועל מה שנאמר \u0003\"כי אנכי בעלתי בכם ולקחתי אתכם אחד מעיר ושנים ממשפחה\"\u0004 (ירמיה ג, יד), \u0003אמר ריש לקיש: דברים ככתבן,\u0004 שרק בודדים יגאלו, והשאר יאבדו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: לא ניחא ליה למרייהו דאמרת להו הכי\u0004 \u0005[נוח לו לאדונם,\u0006 ה', \u0005שאומר אתה להם כך],\u0006 \u0003אלא: אחד מעיר מזכה\u0004 את \u0003כל העיר כולה, ושנים ממשפחה מזכין\u0004 את \u0003כל המשפחה כולה,\u0004 והם נגאלים בזכותם. וכעין זה מסופר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב, ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 שפסוק זה יש לפרשו \u0003דברים ככתבן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: לא ניחא ליה למרייהו דאמרת להו הכי\u0004 \u0005[נוח לו לאדונם,\u0006 ה', \u0005שאומר אתה להם כך],\u0006 \u0003אלא: אחד מעיר מזכה\u0004 את \u0003כל העיר ושנים ממשפחה מזכין\u0004 את \u0003כל המשפחה.\u0004","ואגב מעשה זה מסופר: \u0003חזייה דהוה קא חייף רישיה וסליק ויתיב קמיה\u0004 \u0005[ראה\u0006 רב את רב כהנא \u0005שהוא חופף את ראשו\u0006 ואחר כך \u0005עולה ויושב לפני]\u0006 \u0003רב. אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003\"ולא תמצא בארץ החיים\"\u0004 (איוב כח, יג). חשב רב כהנא שהוא פונה אליו ואומר עליו דברי הכתוב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב: האם \u0003מילט קא לייטת לי\u0004 \u0005[מקלל אתה אותי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קרא קאמינא\u0004 \u0005[פסוק אומר אני]\u0006 ואין זו פניה אליך, אלא להזכירך כי \u0003לא תמצא תורה במי שמחיה\u0004 (מעדן) \u0003עצמו עליה,\u0004 אלא בסובלים דוחק בשעת למודם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין מיעוט הנגאלים לעתיד, \u0003ר' סימאי אומר: נאמר \"ולקחתי אתכם לי לעם\"\u0004 (שמות ו, ז), \u0003ונאמר \"והבאתי אתכם\u0004 אל הארץ\u0003\"\u0004 (שמות ו, ח), \u0003מקיש\u0004 \u0005[משוה]\u0006 הכתוב את \u0003יציאתן ממצרים לביאתן לארץ,\u0004 כיצד? — \u0003מה ביאתן לארץ\u0004 באו רק \u0003שנים מששים ריבוא\u0004 שיצאו, שהרי כולם מתו במדבר ונשארו רק כלב ויהושע בן נון, \u0003אף יציאתן ממצרים שנים מששים ריבוא\u0004 יצאו והשאר נשארו ומתו שם. \u0003ד\u0004\u0003אמר רבא: וכן לימות המשיח,\u0004 שרק מעטים מאד יזכו לגאולה, \u0003שנאמר: \"וענתה שמה כימי נעוריה וכיום עלותה מארץ מצרים\"\u0004 (הושע ב, יז), שאף בגאולה יהיו רק מעטים מרבים","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' יוסי: פעם אחת נכנסתי לאלכסנדריא של מצרים, מצאתי זקן אחד ואמר לי: בא ואראך מה עשו אבותי\u0004 המצריים \u0003לאבותיך\u0004 היהודים, חלק \u0003מהם טבעו בים, מהם הרגו בחרב, מהם מעכו בבנין. ועל דבר זה\u0004 משום שהתרעם בצערו על יסורי ישראל \u0003נענש משה רבינו, שנאמר: \"ומאז באתי אל פרעה לדבר בשמך הרע לעם הזה\u0004 והצל לא הצלת את עמך","\u0003\"\u0004(שמות ה, כג), \u0003אמר לו הקדוש ברוך הוא: חבל על דאבדין ולא משתכחין\u0004 \u0005[חבל על האובדים ואינם נמצאים]\u0006 עוד, אבות האומה שאין כיוצא בהם. \u0003הרי כמה פעמים נגליתי על אברהם יצחק ויעקב באל שדי ולא הרהרו על מדותי, ולא אמרו לי \"מה שמך\", אמרתי לאברהם \"קום התהלך בארץ לארכה ולרחבה כי לך אתננה\"\u0004 (בראשית יג, יז), לבסוף \u0003בקש מקום לקבור את שרה ולא מצא\u0004 לו, \u0003עד שקנה בארבע מאות שקל כסף, ולא הרהר על מדותי,\u0004 ולא התרעם שלא עמדתי בהבטחתי לתת לו את הארץ.","וכן \u0003אמרתי ליצחק \"גור בארץ הזאת ואהיה עמך ואברכך\"\u0004 (בראשית כו, ג), \u0003בקשו עבדיו מים לשתות ולא מצאו עד שעשו מריבה, שנאמר: \"ויריבו רעי גרר עם רעי יצחק לאמר לנו המים\"\u0004 (בראשית כו, כ), \u0003ולא הרהר אחר מדותי.\u0004","וכן \u0003אמרתי ליעקב \"הארץ אשר אתה שכב עליה לך אתננה\"\u0004 (בראשית כח, יג), \u0003ביקש מקום לנטוע אהלו, ולא מצא, עד שקנה במאה קשיטה, ולא הרהר אחר מדותי, ולא אמרו לי \"מה שמך\", ואתה אמרת לי \"מה שמך\" בתחלה,\u0004 ונודעה לך גדולתי יותר ממה שידעו הם, \u0003ועכשיו אתה אומר לי \"והצל לא הצלת את עמך\"\u0004 (שמות ה, כג), \u0003\"עתה תראה את אשר אעשה לפרעה\"\u0004 (שמות ו, א), ויש בכך גם רמז: \u0003במלחמת פרעה\u0004 ומפלתו \u0003אתה רואה, ו\u0004אולם \u0003אי\u0004 (אין) \u0003אתה רואה במלחמת שלשים ואחד מלכים\u0004 שבארץ ישראל, שלא תזכה להנחיל לישראל את הארץ.","נאמר: \u0003\"\u0004ויעבור ה' על פניו ויקרא ה' ה' אל רחום וחנון ארך אפים ורב חסד ואמת. נוצר חסד לאלפים... \u0003וימהר משה ויקד ארצה וישתחו\"\u0004 (שמות לד, ו-ח). ושואלים: \u0003מה ראה משה\u0004 במיוחד כאן במדות אלה שמיהר והשתחווה?","\u0003ר' חנינא בן גמלא אמר:\u0004 מידת \u0003\"ארך אפים\" ראה, ורבנן אמרי\u0004 \u0005[אומרים]\u0006 \u0003\"אמת\" ראה. תניא כמאן דאמר\u0004 \u0005[שנויה\u0006 ברייתא \u0005כ\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003\"ארך אפים\" ראה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשעלה משה למרום מצאו להקדוש ברוך הוא שיושב וכותב \"ארך אפים\", אמר לפניו: רבונו של עולם! ארך אפים\u0004 כוונתו בוודאי \u0003לצדיקים, אמר לו\u0004 הקדוש ברוך הוא: \u0003אף לרשעים. אמר ליה\u0004 \u0005[לו]\u0006 משה: \u0003רשעים יאבדו! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003השתא חזית מאי דמבעי\u0004 \u0005[עכשיו תראה מה שתצטרך]\u0006 \u0003לך,\u0004","\u0003כשחטאו ישראל\u0004 במרגלים וביקש משה רחמים עליהם \u0003אמר לו\u0004 הקדוש ברוך הוא למשה: \u0003לא כך אמרת לי\u0004 שאהיה \u0003ארך אפים לצדיקים\u0004 בלבד? ואם כן אינם ראוים לסליחה."],["\u0003אמר לפניו: רבונו של עולם! ולא כך אמרת לי,\u0004 שאתה מאריך \u0003אף לרשעים? והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ועתה יגדל נא כח ה' כאשר דברת לאמר\"\u0004 (במדבר יד, יז), משמע שחוזר ומזכיר כביכול הבטחת ה', בענין זה.","מסופר: \u0003ר' חגא הוה סליק ואזיל בדרגא דבי\u0004 \u0005[היה עולה והולך במדרגות בית]\u0006 \u0003רבה בר שילא, שמעיה לההוא ינוקא דאמר\u0004 \u0005[שמע תינוק אחד שאומר]\u0006 \u0003\"עדתיך נאמנו מאד לביתך נאוה קדש ה' לארך ימים\"\u0004 (תהלים צג, ה) ולמד מכאן שגם אריכות אפים של ה' לאורך ימים, \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"תפלה למשה\"\u0004 (תהלים צ, א), לומר שפרק זה אף הוא מדבריו של משה רבינו הוא. \u0003אמר\u0004 כששמע דברים אלה: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדת \u0003ארך אפים ראה\u0004 ועל כך שיבח.","\u0003אמר ר' אלעזר אמר ר' חנינא: עתיד הקדוש ברוך הוא להיות עטרה בראש כל צדיק וצדיק,\u0004 שיתן מזיוו עליו, \u0003שנאמר: \"ביום ההוא יהיה ה' צבאות לעטרת צבי ולצפירת תפארה לשאר עמו\"\u0004 (ישעיה כח, ה), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לעטרת צבי ולצפירת תפארה\"?\u0004 — \u0003לעושים רצונו\u0004 (\"צבי\" — לשון רצון בארמית) \u0003ומצפים\u0004 (\"צפירה\") \u0003לישועתו, יכול\u0004 יהא עטרת \u0003לכל\u0004 — \u0003תלמוד לומר: \"לשאר עמו\"\u0004 — \u0003למי שמשים עצמו כשירים\u0004 מתוך ענוה.","ועוד נאמר שם \u0003\"ולרוח משפט ליושב על המשפט ולגבורה משיבי מלחמה שערה\"\u0004 (ישעיה כח, ו), \u0003\"ולרוח משפט\"\u0004 — \u0003זה הרודה את יצרו\u0004 וכופהו מלחטוא, \u0003\"וליושב על המשפט\"\u0004 — \u0003זה הדן דין אמת לאמיתו, \"ולגבורה\"\u0004 — \u0003זה המתגבר ביצרו, \"משיבי מלחמה\"\u0004 — \u0003זה שנושא ונותן במלחמתה של תורה, \"שערה\"\u0004 — \u0003אלו שמשכימין ומעריבין בבתי כנסיות ובתי מדרשות.\u0004","\u0003אמרה מדת הדין לפני הקדוש ברוך הוא: רבונו של עולם! מה נשתנו אלו מאלו\u0004 מה דינם של אחרים העוסקים בתורה ואין בהם מדות טובות אלה? \u0003אמר לה: \"וגם אלה ביין שגו ובשכר תעו.. פקו פליליה\"\u0004 (שם ז), \u0003ואין \"פוקה\" אלא גיהנם, שנאמר\u0004 בדברי אביגיל לדוד: \u0003\"\u0004ו\u0003לא תהיה זאת לך לפוקה\"\u0004 (שמואל א' כה, לא), \u0003ואין\u0004 משמעות לשון \u0003\"פלילה\" אלא דיינין, שנאמר: \"ונתן בפללים\"\u0004 (שמות כא, כב), שאנשים שלא עסקו כך בתורה תעו ושגו, ואין ראוים למתן שכר, אלא להיפך מזה.","\u0003אנשי עיר הנדחת אין להם חלק לעולם הבא, שנאמר: \"יצאו אנשים בני בליעל מקרבך וידיחו את ישבי עירם\"\u0004 (דברים יג, יד). \u0003ואינן נהרגים\u0004 בדין עיר הנדחת \u0003עד\u0004 שיתקיימו כמה וכמה תנאים: \u0003שיהיו מדיחיה מאותה העיר, ומאותו השבט, ועד שיודח רובה\u0004 של העיר, \u0003ועד שידיחוה אנשים\u0004 (גברים). ואולם אם \u0003הדיחוה נשים\u0004 או \u0003קטנים, או שהודח\u0004 רק \u0003מיעוטה\u0004 של העיר, \u0003או שהיו מדיחיה חוצה לה\u0004 ולא מבני העיר והשבט — בכל אלה \u0003הרי אלו\u0004 נדונים \u0003כיחידים.\u0004 וכדי לדון את העיר \u0003צריכין\u0004 כל בני העיר \u0003שני עדים והתראה לכל אחד ואחד\u0004 שאכן עבד עבודה זרה.","\u0003זה חומר ב\u0004דינם של \u0003יחידים\u0004 העובדים עבודה זרה \u0003מבמרובים\u0004 (תושבי עיר שלמה שהודחו) — \u0003שהיחידים\u0004 שעובדים עבודה זרה נידונים \u0003ב\u0004מיתה חמורה של \u0003סקילה, לפיכך ממונם פלט\u0004 (ניצל) וניתן ליורשיהם. \u0003ו\u0004אילו \u0003המרובין\u0004 נדונים \u0003בסייף, לפיכך ממונם\u0004 כולו \u0003אבד,\u0004 שמחרימים את כל העיר.","נאמר: \u0003\"הכה תכה את ישבי העיר ההיא לפי חרב\"\u0004 (דברים יג, טז), לומר כי \u0003החמרת\u0004 (שיירת חמורים) \u0003והגמלת\u0004 (שיירת גמלים) \u0003העוברת ממקום למקום\u0004 — \u0003הרי אלו מצילין אותה.\u0004","שאם היו בעיר ולא נדחו לעבודה זרה — מצטרפים להיות כרובה של עיר להצילה מהשמדה, \u0003שנאמר: \"החרם אתה ואת כל אשר בה ואת בהמתה לפי חרב\"\u0004 (דברים יג טז) \u0003מכאן אמרו: נכסי צדיקים\u0004 (שלא חטאו בעבודה זרה) שהיו \u0003בתוכה\u0004 — \u0003אובדין\u0004 עם כל העיר, אבל \u0003שבחוצה לה פליטין\u0004 (ניצלים). ונכסים \u0003של רשעים, בין\u0004 שהיו \u0003בתוכה בין שבחוצה לה\u0004 — \u0003הרי אלו אובדין,\u0004","\u0003שנאמר: \"ואת כל שללה תקבץ אל תוך רחבה\"\u0004 (דברים יג יז). ו\u0003אם אין לה רחוב\u0004 לאותה עיר — \u0003עושין לה רחוב\u0004 כדי לקיים בה כלשון הכתוב, \u0003היתה רחבה חוצה לה\u0004 מחוץ לחומתה — \u0003כונסין אותה לתוכה,\u0004 שמוסיפים חומה שתכלול גם את הרחוב,","\u0003שנאמר: \"ושרפת באש את העיר ואת כל שללה כליל לה' אלהיך\"\u0004 (דברים יג יז), ומדייקים: \u0003\"שללה\"\u0004 — \u0003ולא שלל שמים, מכאן אמרו: ההקדשות שבה\u0004 שהוקדשו לשמים ואינם עוד רכוש אנשי העיר — \u0003יפדו, ותרומות\u0004 — לא יאכלו ולא ישרפו, אלא \u0003ירקבו, מעשר שני וכתבי הקדש\u0004 שהיו בה — \u0003יגנזו.\u0004","על הנאמר \u0003\"כליל לה' אלהיך\", אמר ר' שמעון: אמר הקדוש ברוך הוא, אם אתם עושין דין בעיר הנדחת\u0004 — \u0003מעלה אני עליכם כאילו אתם מעלים עולה כליל לפני.\u0004","ומה שנאמר \u0003\"והיתה תל עולם\"\u0004 (דברים יג יז), כוונתו: \u0003לא תעשה\u0004 אפילו מקום \u0003גנות ופרדסים,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר,\u0004 מה שנאמר: \u0003\"לא תבנה עוד\",\u0004 הכוונה: \u0003לכמות שהיתה אינה נבנית, אבל נעשית היא גנות ופרדסים. \"ולא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג יח) — \u0003שכל זמן שהרשעים בעולם\u0004 — \u0003חרון אף בעולם\u0004 כולו, \u0003אבדו רשעים מן העולם\u0004 — \u0003נסתלק חרון אף מן העולם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש הכתוב \"יצאו אנשים בני בליעל מקרבך וידיחו את יושבי עירם לאמור נלכה ונעבדה אלהים אחרים אשר לא ידעתם\" (דברים יג יד), \u0003\"יצאו\"\u0004 כוונתו — \u0003הן,\u0004 המדיחים עצמם, \u0003ולא שלוחין\u0004 ששלחו להדחה. \u0003\"אנשים\"\u0004 — \u0003אין אנשים פחות משנים,\u0004 שמיעוט רבים שנים. \u0003דבר אחר: \"אנשים\"\u0004 להדגיש: \u0003ולא נשים. \"אנשים\"\u0004 — \u0003ולא קטנים.\u0004","\u0003\"בני בליעל\"\u0004 — \u0003בנים שפרקו עול שמים מצואריהם. \"מקרבך\"\u0004 — ללמד שעיר זו היא בתוך ישוב ישראל \u0003ולא מן הספר,\u0004 שאז אין נוהגים בה בדין זה. \u0003\"ישבי עירם\"\u0004 — \u0003ולא יושבי עיר אחרת. \"לאמר\"\u0004 — רמז \u0003שצריכין עדים והתראה\u0004 (\"לאמר\") \u0003לכל אחד ואחד\u0004 שחטא.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה, \u0003ר' יוחנן אמר: חולקין עיר אחת\u0004 שתהא נחלה \u0003לשני שבטים\u0004 יחד, \u0003וריש לקיש אמר: אין חולקין עיר אחת לשני שבטים. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו במשנתנו: \u0003עד שיהו מדיחיה מאותה העיר ומאותו שבט, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מדיחיה מאותה העיר, אי איכא\u0004 \u0005[אם יש]\u0006 גם תנאי זה שהם \u0003מאותו שבט\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא,\u0004 ולכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003חולקין עיר אחת לשני שבטים,\u0004 שאם לא כן הרי יושבי העיר הם ממילא גם בני אותו שבט!","ודוחים: \u0003לא,\u0004 אין זו הוכחה, יתכן ש\u0003נפלה ליה\u0004 \u0005[לו]\u0006 נחלה בעיר זו \u0003בירושה\u0004 מצד אמו שהיתה משבט אחר. \u0003אי נמי דיהבוה ניהליה\u0004 \u0005[שנתנו לו אותה]\u0006 נחלה \u0003במתנה,\u0004 אבל בחלוקה לשבטים אין נותנים עיר אחת לשני שבטים יחד.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן לריש לקיש: נאמר בהקצאת ערים ללויים \u0003\"ערים תשע מאת שני השבטים האלה\"\u0004 (יהושע כא, טז), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003ארבע ופלגא מהאי וארבע ופלגא מהאי\u0004 \u0005[ארבע וחצי מ\u0006שבט \u0005זה, וארבע וחצי מזה]\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003חולקין עיר אחת לשני שבטים!\u0004 ודוחים: \u0003לא, ארבעה מהאי\u0004 \u0005[מ\u0006שבט \u0005זה]\u0006 \u0003וחמש מהאי\u0004 \u0005[מ\u0006שבט \u0005זה]\u0006 והקשה לו:","\u0003אי הכי לפרוש פרושי\u0004 \u0005[שיפרש]\u0006 איזה שבט נתן את העיר היתירה!"],["ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר לשיטתו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים השאלה\u0005]:\u0006 \u0003הודחו\u0004 בני עיר הנדחת \u0003מאליהן\u0004 בלא מדיחים, \u0003מהו\u0004 דינם? וצדדי השאלה: \u0003\"וידיחו\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ללמד: \u0003ולא שהודחו מאליהן. או דילמא\u0004 \u0005[שמא]\u0006 הדין כן \u0003אפילו\u0004 כאשר \u0003הודחו מאליהן.\u0004","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003הדיחוה נשים וקטנים\u0004 אינה קרויה עיר הנדחת, והם ניצולים, \u0003אמאי\u0004 \u0005[\u0006ו\u0005מדוע]\u0006 נאמר כן? \u0003ליהוי\u0004 \u0005[שיהיו]\u0006 \u0003כהודחו מאליהן,\u0004 אם כן משמע שהמודחים מאליהם — פטורים! ודוחים: אין להשוות, \u0003הנך בתר נפשייהו גרידי\u0004 \u0005[אלה\u0006 שהודחו מאליהם \u0005אחרי עצמם\u0006 הם \u0005נגררים],\u0006 ועושים בכל לבם, ושמא הם חייבים, \u0003הני בתר\u0004 \u0005[אלה אחר]\u0006 \u0003נשים וקטנים גרידי\u0004 \u0005[\u0006הם \u0005נגררים],\u0006 ואינם אדוקים בעבודה זרה. ואם כן אי אפשר להוכיח דבר.","במשנה שנינו שאין דנים את העיר \u0003עד שיודח רובה.\u0004 ושואלים: \u0003היכי עבדינן\u0004 \u0005[כיצד אנו עושים]\u0006 למעשה לקבוע שאכן הודח רובה? \u0003אמר רב יהודה: דנין\u0004 כל אחד מבני העיר, \u0003וחובשין\u0004 אותו בבית הסוהר, \u0003דנין וחובשין\u0004 עד שמגיעים לרובה של עיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא: נמצא אתה מענה את דינן של אלו\u0004 שנידונו כבר שהם יושבים ויודעים שהם חייבי מיתה, והרי אסור לענות את הדין! \u0003אלא אמר עולא: דנין וסוקלין, דנין וסוקלין\u0004 עד שמגיעים לחצי העיר, ומכאן והלאה דנים בסייף.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בדבר גם חכמים אחרים, \u0003ר' יוחנן אמר: דנין וסוקלין, דנין וסוקלין, וריש לקיש אמר: מרבין להן בתי דינין\u0004 וכל אחד מבתי הדין דן אחד מבני העיר, כדי שידונו בבת אחת.","ושואלים: \u0003איני\u0004 \u0005[וכי כן]\u0006 הוא?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חמא בר יוסי אמר ר' אושעיא:\u0004 נאמר \u0003\"והוצאת את האיש ההוא או את האשה ההיא...\u0004 אל שעריך\u0003\"\u0004 (דברים יז, ה) ולמדים: \u0003איש ואשה אתה מוציא לשעריך\u0004 ודן בבית דין מקומי, \u0003ואי\u0004 (אין) \u0003אתה מוציא כל העיר כולה לשעריך,\u0004 אלא נדונים בסנהדרי גדולה! \u0003אלא\u0004 כך עושים: \u0003מרבין להן בתי דינין ומעיינין בדיניהן,\u0004 וכאשר הגיעו למסקנה שרובם עבדו עבודה זרה אין גומרים את דינם, אלא \u0003מסקינן להו\u0004 \u0005[מעלים אותם]\u0006 \u0003לבית דין הגדול, וגמרי להו לדינייהו, וקטלי להו\u0004 \u0005[וגומרים את דינם, והורגים אותם].\u0006","נאמר: \u0003\"הכה תכה את ישבי העיר\u0004 החרם אותה ואת כל אשר בה ואת בהמתה לפי חרב\u0003\"\u0004 (דברים יג, טז). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החמרת\u0004 (שיירת חמורים) \u0003והגמלת\u0004 (שיירת גמלים) \u0003העוברת ממקום למקום, לנו בתוכה והודחו עמה, אם נשתהו שם שלשים יום\u0004 — \u0003הן\u0004 נידונים \u0003בסייף וממונן אבד,\u0004 אם שהו שם \u0003פחות מיכן\u0004 (מכך) — \u0003הן\u0004 נידונים \u0003בסקילה\u0004 כיחידים, \u0003וממונן פלט.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003כמה יהיה\u0004 אדם \u0003בעיר ויהיה\u0004 דינו \u0003כאנשי העיר\u0004 לכל חיובי צדקה ומיסים — \u0003שנים עשר חדש,\u0004 ולא שלשים יום! \u0003אמר רבא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהות שנים עשר חודש — כדי \u0003למיהוי מבני מתא\u0004 \u0005[להיות מבני העיר],\u0006 \u0003הא למיהוי מיתבי מתא\u0004 \u0005[וזה להיות מיושבי העיר]\u0006 דיו בשלושים יום.","\u0003והתניא\u0004 \u0005[ו\u0006אכן כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המודר הנאה מבני העיר\u0004 (שנדר שאינו רוצה ליהנות מבני עיר מסויימת), \u0003אם יש אדם שנשתהא שם שנים עשר חדש\u0004 — \u0003אסור ליהנות ממנו,\u0004 שהריהו מבני העיר. שהה שם \u0003פחות מיכן\u0004 — \u0003מותר ליהנות ממנו.\u0004 אם נדר שייאסר \u0003ביושבי העיר,\u0004 מי ש\u0003נשתהא שלשים יום\u0004 — \u0003אסור ליהנות ממנו, פחות מיכן\u0004 — \u0003מותר ליהנות ממנו.\u0004 וכיון שבעיר הנדחת נאמר \"יושבי העיר\", הרי בכלל זה כל ששהו בה שלושים יום.","נאמר: \u0003\"החרם אתה ואת כל אשר בה\"\u0004 (דברים יג, טז). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"החרם אותה ואת כל אשר בה\",\u0004 הרי זה בא למעט: \u0003פרט לנכסי צדיקים שבחוצה לה\u0004 שאין מחרימים אותם, \u0003\"ואת כל אשר בה\"\u0004 — \u0003לרבות נכסי צדיקים שבתוכה.\u0004 עוד נאמר \"ואת כל שללה תקבץ אל תוך רחובה\" (דברים יג יז), \u0003\"שללה\"\u0004 כוונתו: של אנשי העיר \u0003ולא שלל שמים,\u0004 שחפצים השייכים להקדש אינם בכלל זה, \u0003\"ואת כל שללה\"\u0004 בא \u0003לרבות נכסי רשעים שחוצה לה\u0004 לשריפה.","\u0003אמר ר' שמעון: מפני מה אמרה תורה נכסי צדיקים שבתוכה יאבדו,\u0004 ומדוע מענישים אותם על חטאי אחרים? אלא \u0003מי גרם להם\u0004 לצדיקים \u0003שידורו בתוכה,\u0004 בעיר זו של רשעים — \u0003ממונם\u0004 שקשרם לעיר זו, \u0003לפיכך ממונם אבד.\u0004 \u0003ד\u0004\u0003אמר מר\u0004 \u0005[החכם]:\u0006 הכתוב \u0003\"ואת כל שללה תקבץ\"\u0004 (דברים יג יז) נדרש: \u0003לרבות נכסי רשעים שבחוצה לה\u0004 אף הם נשרפים עמה. \u0003אמר רב חסדא: ובנקבצים לתוכה,\u0004 כלומר, דברים שאפשר לקבוץ בו ביום לתוך העיר.","\u0003אמר רב חסדא: פקדונות של אנשי עיר הנדחת מותרין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]?\u0006 מה היתה כוונת רב חסדא? \u0003אי לימא\u0004 \u0005[אם תאמר]\u0006 שמדובר בפקדונות השייכים ל\u0003עיר אחרת ואיתנהו בגוה\u0004 \u0005[ונמצאים בתוכה]\u0006 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003מותרין,\u0004 הרי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003\"שללה\" הוא,\u0004 אלא רכוש אחרים. \u0003ואלא\u0004 תאמר כי מדובר בפקדונות \u0003דידהו\u0004 \u0005[שלהם]\u0006 \u0003ואיתנהו\u0004 \u0005[וישנם]\u0006 \u0003בעיר אחרת,\u0004 אם כן יש לדון בהם כבשאר נכסי העיר, \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003נקבצין לתוכה\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מותרין,\u0004 הרי כבר אמרנו שנכסי רשעים אובדים! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אין נקבצין לתוכה\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה חדא זימנא\u0004 \u0005[פעם אחת]\u0006 להלכה זו שנכסים שאין נקבצים אין שורפים.","ומשיבים: \u0003לא, לעולם\u0004 מדובר בנכסים של \u0003עיר אחרת דמפקדי בתוכה\u0004 \u0005[שמופקדים בתוכה],\u0006 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003כגון דקביל עליה\u0004 \u0005[שקיבל עליו,\u0006 על עצמו\u0005]\u0006 בן העיר הנדחת שהחזיק בפקדון \u0003אחריות.\u0004 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דקביל עליה\u0004 \u0005[שקיבל עליו]\u0006 \u0003אחריות\u0004 — \u0003כדידיה דמי\u0004 \u0005[כשלו\u0006 הם \u0005נחשבים]\u0006 ויאבדו עם רכושו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","\u0003אמר רב חסדא: בהמה\u0004 שהיתה \u0003חציה של עיר הנדחת וחציה של עיר אחרת\u0004 — \u0003אסורה\u0004 כולה. \u0003עיסה,\u0004 השייכת \u0003חציה של עיר הנדחת וחציה של עיר אחרת\u0004 — \u0003מותרת\u0004 בחלקה השייך לעיר אחרת. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? ומסבירים: \u0003בהמה כמאן דלא פליגא דמיא\u0004 \u0005[כמי שאינה חלוקה\u0006 היא \u0005נחשבת],\u0006 שהרי אי אפשר להשתמש לאכילה בחצי בהמה, שכן אינה נאכלת בלא שחיטה שהיא מעשה בכולה, וכיון שלא שייך לחלקה בעודה בחיים, הריהי נחשבת בשל כך לדבר שלם, ומכיון שנאסר חלקה — נאסרה כולה. ואילו \u0003עיסה כמאן דפליגא דמיא\u0004 \u0005[כמי שחלוקה נחשבת],\u0006 שלצורך חלוקה נעשתה, וודאי מחלקים אותה, ולכן רק חציה אסור.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חסדא: בהמת עיר הנדחת מהו דתיתהני\u0004 \u0005[שתועיל]\u0006 \u0003בה\u0004 \u0003שחיטה\u0004 לפחות כדי \u0003לטהרה מידי\u0004 טומאת \u0003נבילה?\u0004 שאם הורגים את בהמות העיר הרי הן נעשות נבילה ומטמאות במגע ובמשא, והאם אפשר לשחטה קודם שתהרג, כדי שלא תטמא. וצדדי השאלה: האם \u0003\"לפי חרב\"\u0004 (דברים יג טז) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומשמעו — \u0003לא שנא שחטה משחט, לא שנא קטלא מקטל\u0004 \u0005[אינו שונה\u0006 אם \u0005שחט אותה, אינו שונה\u0006 אם \u0005הורג אותה]\u0006 באופן אחר תמיד אינה ראויה וכנבילה היא, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003שחטה מהניא\u0004 \u0005[מועילה]\u0006 \u0003לה\u0004 ה\u0003שחיטה,\u0004 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 לשאלה זו לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף: שיער נשים צדקניות\u0004 שבעיר \u0003מהו\u0004 דינו? \u0003אמר רבא:\u0004 מה מקום לשאלה זו, \u0003הא\u0004 \u0005[הרי]\u0006 מדבריך משמע ששער של \u0003רשעיות אסור?\u0004 ואולם הלא \u0003\"תקבץ... ושרפת\" כתיב\u0004 \u0005[נאמר]\u0006 (דברים יג, יז), ללמד: \u0003מי שאינו מחוסר אלא קביצה ושריפה, יצא זה,\u0004 השיער, \u0003ש\u0004הוא \u0003מחוסר תלישה וקביצה ושריפה.\u0004 ואם כן שיער נשים אינו נאסר כלל!","\u0003אלא אמר רבא:\u0004 השאלה היא לגבי \u0003פיאה נכרית.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 הדבר\u0005]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003מחובר\u0004 הפאה הנכרית \u0003בגופה\u0004 — \u0003כגופה דמיא\u0004 \u0005[נחשב]\u0006 ונדונו כגופה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דתלי בסיבטא\u0004 \u0005[כשתלויה\u0006 הפיאה \u0005ביתד]\u0006 ויש לברר: האם \u0003כנכסי צדיקים שבתוכה דמי\u0004 \u0005[נחשב]\u0006 — \u0003ואבד, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דעיילא ונפקא\u0004 \u0005[שנכנסת ויוצאת\u0006 בפיאה\u0005]\u0006 ולבושה בה לעתים קרובות \u0003כלבושה דמי\u0004 \u0005[נחשב]?\u0006 אף לשאלה זו לא נמצאה פתרון, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","על הנאמר \u0003\"ואת כל שללה תקבץ אל תוך רחבה\"\u0004 (דברים יג, יז), \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על כתוב זה: \u0003אין לה\u0004 לעיר \u0003רחוב\u0004 — \u0003אינה נעשית עיר הנדחת\u0004 שהרי אין הכתוב מתקיים בה, אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: אין לה רחוב\u0004 — \u0003עושין לה רחוב.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 ומסבירים: \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' ישמעאל \u0003סבר\u0004 \u0005[סבור]\u0006 כי מה שנאמר \u0003\"רחובה\"\u0004 — \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע,\u0004 ואם לא היה מתחילה אינו קרוי \"רחובה\", \u0003ומר\u0004 \u0005[וחכם זה\u0006 ר' עקיבא\u0005]\u0006 \u0003סבר:\u0004 \u0005[סבור]\u0006 כי מה שנאמר \u0003\"רחובה\"\u0004 — \u0003השתא נמי משמע\u0004 \u0005[של עכשיו גם כן משמע]\u0006 \"רחובה\", ודנים את העיר לשריפה."],["שנינו במשנה כי \u0003ההקדשות שבה יפדו,\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003היו בה קדשי קדשים, קדשי מזבח\u0004 (בהמות המוקדשות לצורך קרבנות) — \u0003ימותו,\u0004 שגורמים להם מיתה, \u0003קדשי בדק הבית\u0004 — \u0003יפדו, ותרומות\u0004 — \u0003ירקבו, ומעשר שני וכתבי הקדש\u0004 — \u0003יגנזו, ר' שמעון אומר:\u0004 לא כן, אלא נאמר \u0003\"בהמתה\",\u0004 והרי זה בא להוציא — \u0003ולא בהמת בכור ומעשר\u0004 שאינה שייכת קודם לעיר הנדחת. \u0003\"שללה\"\u0004 — \u0003פרט לכסף הקדש וכסף מעשר.\u0004","ומפרשים את הדברים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003היו בה קדשי קדשים, קדשי מזבח ימותו.\u0004 ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003ימותו? ירעו עד שיסתאבו\u0004 (יפול בהם מום) ואז \u0003ימכרו, ויפלו דמיהן לנדבה\u0004 (קרבן נדבה למזבח).","\u0003ר' יוחנן אמר:\u0004 טעם הדבר הוא ככתוב \u0003\"זבח רשעים תועבה\"\u0004 (משלי כא, כז), ואין רוצים שמממון רשעים ייעשה זבח. \u0003ריש לקיש אמר: ממון בעלים הוא\u0004 קרבן זה, שאינו לגמרי ממון גבוה, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בקדשים שחייב באחריותן\u0004 אנו דנים, שהתנדב קדשים אלה, ואמר שמקבל על עצמו לשלם אם יאבדו, וכיון שאחריותם עליו הרי הם כשאר ממונו, \u0003ו\u0004כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שקדשים שחייב באחריותם \u0003ממון בעלים הוא.\u0004","ועל הסבר זה מקשים: \u0003הא מדסיפא\u0004 \u0005[מאחר שסופה]\u0006 של אותה ברייתא מפורש שכשיטת \u0003ר' שמעון היא,\u0004 משמע ש\u0003רישא לאו\u0004 \u0005[תחילתה לא]\u0006 כשיטת \u0003ר' שמעון,\u0004 ואי אפשר לפרש כן. אלא יש להסביר שמדובר \u0003בקדשים קלים, ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יוסי הגלילי\u0004 ש\u0003אמר: קדשים קלים ממון בעלים\u0004 הם, ומדייקים \u0003אבל קדשי קדשים מאי\u0004 \u0005[מה\u0006 דינם\u0005]\u0006 — \u0003יפדו,\u0004","\u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה בסופה]\u0006 של אותה ברייתא \u0003\"קדשי בדק הבית יפדו\", ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בתוך\u0006 הלכה זו \u0005עצמה]\u0006 באופן זה: \u0003במה דברים אמורים\u0004 — \u0003בקדשים קלים, אבל קדשי קדשים\u0004 — \u0003יפדו!\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 בין קדשי הקדשים קרבן חטאת, והבעלים שהפרישו את הקרבן נהרגים והרי זו אם כן \u0003חטאת שמתו בעליה,\u0004 ולפי ההלכה חטאת כזו דינה היא ש\u0003למיתה אזלא\u0004 \u0005[\u0006היא \u0005הולכת],\u0006 מכיון שכך, \u0003לא פסיקא ליה\u0004 \u0005[אינה פסוקה,\u0006 גמורה, \u0005לו]\u0006 ההלכה ביתר קדשי קדשים, שיוכל לקבוע דין זה תמיד, ולכן נקט בדבר שהוא הלכה פסוקה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' יוחנן לא אמר כריש לקיש\u0004 יש טעם לדבר \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"זבח רשעים תועבה\"\u0004 ועל פסוק זה הוא סומך. \u0003אלא ריש לקיש, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן? אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 \u0003\"זבח רשעים תועבה\"\u0004 — \u0003הני מילי היכא דאיתנהו בעינייהו\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כש\u0006הם \u0005נמצאים בעינם\u0006 בעצמם\u0005]\u0006 כשיקריב בהמה עצמה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003כיון דאישתני אישתני\u0004 \u0005[שהשתנו השתנו]\u0006 — ששוב אינם בעינם, ואין בהם איסור.","שנינו בברייתא ש\u0003ר' שמעון אומר\u0004 שהכתוב \u0003\"בהמתך\"\u0004 בא להוציא — \u0003ולא בהמת בכור ומעשר.\u0004 ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים],\u0006 באיזה קרבן בכור ומעשר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בתמימין,\u0004 באלה שלא נפל בהם מום, אם כן הרי אלה כשאר קדשים הם, שאינם שייכים כלל לעיר ו\u0003שלל שמים הוא. אלא\u0004 ודאי מדובר \u0003ב\u0004בכורות \u0003בעלי מומין\u0004 שהם רכוש הבעלים ואם כן \u0003\"שללה\" נינהו\u0004 \u0005[הם],\u0006 ומה טעמו של ר' שמעון!","\u0003אמר רבינא: לעולם\u0004 מדובר \u0003בבעלי מומין,\u0004 וכך יש להבין את דברי ר' שמעון: המצוה לבער הכל היא לגבי \u0003מי שנאכל בתורת \"בהמתך\"\u0004 שהוא רכוש פרטי של בני עיר הנדחת, \u0003יצאו אלו\u0004 בכור ומעשר (אפילו במומם) \u0003שאין נאכלין\u0004 בכל זאת \u0003בתורת \"בהמתך\", אלא בתורת בכור ומעשר\u0004 שהם מתנות הנתונות לכהנים ש\u0003שלל שמים נינהו\u0004 \u0005[הם]\u0006 מצד שמם לפחות.","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו כולה על דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: הכל קרב והכל נפדה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 שהרי אין דברים אלה מובנים. ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל\u0004 קרבן \u0003שקרב\u0004 למזבח \u0003כשהוא תם, ונפדה כשהוא בעל מום\u0004 — \u0003מ\"שלל\" אימעיט\u0004 \u0005[נתמעט],\u0006 שאינו שייך לעיר הנדחת, אלא שלל שמים הוא, \u0003וכל שקרב כשהוא תם, ואינו נפדה כשהוא בעל מום, כגון בכור \"ומעשר\", מ\"בהמה\"\u0004 (\"בהמתך\") \u0003נפקא\u0004 \u0005[יוצא],\u0006 שאין אלה בהמות העיר ואינן בכלל נכסי העיר.","שנינו בברייתא כי \u0003תרומות ירקבו. אמר רב חסדא: לא שנו אלא תרומה\u0004 שהיתה \u0003ביד ישראל\u0004 ולא הספיק לתת אותה לכהן מסוים, \u0003אבל תרומה\u0004 שנמסרה כבר \u0003ביד כהן\u0004 הגר בעיר הנדחת, \u0003כיון דממוניה\u0004 \u0005[שממונו,\u0006 רכושו\u0005]\u0006 \u0003הוא\u0004 — \u0003תשרף.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף\u0004 ממה ששנינו במשנתנו \u0003\"מעשר שני וכתבי הקדש יגנזו\" והא\u0004 \u0005[והרי]\u0006 \u0003מעשר שני ביד ישראל כתרומה ביד כהן דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי מותר לו לאוכלו וליהנות ממנו בירושלים, \u0003וקתני\u0004 \u0005[ושנינו]\u0006 בכל זאת: \u0003יגנזו! אלא אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר],\u0006 \u0003אמר רב חסדא: לא שנו אלא תרומה ביד כהן,\u0004 שאף שהיא רכושו יש בה קדושת תרומה, \u0003אבל תרומה ביד ישראל\u0004 שאינה כלל כרכושו — \u0003תנתן לכהן שבעיר אחרת\u0004 ולא תרקב כלל.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003עיסה של מעשר שני פטורה מן החלה\u0004 לפי שהוא ממון גבוה, אלו \u0003דברי ר' מאיר, וחכמים מחייבין\u0004 אותה בהפרשת חלה. \u0003אמר רב חסדא: מחלוקת\u0004 זו היא \u0003במעשר שני בירושלים,\u0004 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 ש\u0003מעשר שני ממון גבוה הוא,\u0004 אלא שנתנה התורה זכות לבעליו לאכלו. וכיון שממון גבוה הוא אין מפרישים ממנו מתנות כהונה, \u0003ורבנן סברי\u0004 \u0005[סבורים]\u0006 ש\u0003ממון הדיוט הוא, אבל\u0004 עיסת מעשר שני \u0003בגבולין\u0004 (מחוץ לירושלים) — \u0003דברי הכל פטור,\u0004 שהרי בגבולים אסורה היא באכילה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף\u0004 ממה ששנינו במשנתנו: \u0003מעשר שני וכתבי הקדש יגנזו. במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר במעשר שני \u0003בירושלים,\u0004 ואולם ירושלים \u0003מי הויא\u0004 \u0005[האם\u0006 היא \u0005נעשית]\u0006 אי פעם \u0003עיר הנדחת? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשרה דברים נאמרו בירושלים, וזו אחת מהן: אינה נעשית\u0004 לעולם \u0003עיר הנדחת! ואלא\u0004 הכוונה שהיה המעשר \u0003בעיר אחרת\u0004 שנעשתה עיר נדחת \u0003ואסקוהו לגוה\u0004 \u0005[והכניסוה לתוכה],\u0006 לתוך ירושלים קודם שהוכרזה לעיר הנדחת, \u0003הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 \u0003קלטוהו\u0004 ה\u0003מחיצות\u0004 של ירושלים ואינו קשור עוד לעיר הנדחת, והיה צריך להיות מותר אף באכילה!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במעשר שהיה \u0003בגבולין, וקתני\u0004 \u0005[ושנינו]\u0006 בכל זאת: \u0003יגנזו,\u0004 משמע שמעשר שני אינו נחשב לרכוש שמים אלא כשייך לעיר הנדחת! ודוחים: \u0003לא, לעולם\u0004 מדובר שהיה זה מעשר של \u0003עיר אחרת\u0004 שהודחה \u0003ואסקוהו לגוה\u0004 \u0005[והכניסוהו לתוכה]\u0006 של ירושלים \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003שנטמא\u0004 אותו מעשר ואסור באכילה, ואין לו תקנה אלא גניזה.","ומקשים: \u0003ולפרקיה\u0004 \u0005[ושיפדוהו]\u0006 בירושלים עצמה, ש\u0003אמר ר' אלעזר: מניין למעשר שני שנטמא שפודין אותו אפילו בירושלים\u0004 — \u0003תלמוד לומר:\u0004 \"וכי ירבה ממך הדרך כי \u0003לא תוכל שאתו...\u0004 ונתתה בכסף\" (דברים יד, כד-כה), \u0003ואין\u0004 משמעות לשון \u0003\"שאת\" אלא אכילה, שנאמר: \"וישא משאת מאת פניו\"\u0004 (בראשית מג, לד), משמע שמעשר שאי אפשר לאוכלו (\"לא תוכל שאתו\") אם מפני המרחק מירושלים, ואם מפני הטומאה — מותר לפדותו, ואם כן, שיפדו מעשר זה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 לא במעשר עצמו שנטמא אלא שהיה זה כבר דבר שהוא \u0003לקוח\u0004 (קנוי) בכסף מעשר, שנטמא."],["ושואלים: \u0003וליפרקיה\u0004 \u0005[ושיפדוהו]\u0006 אף את הלקוח בכסף מעשר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלקוח בכסף מעשר שנטמא\u0004 — \u0003יפדה!\u0004 ומשיבים: דברינו היו לשיטת \u0003ר' יהודה\u0004 ש\u0003אמר:\u0004 הלקוח בכסף מעשר שנטמא — \u0003יקבר,\u0004 שאין לו פדיון עוד. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנו מתרצים באופן זה וכשיטה זו, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 נאמרה ההלכה ב\u0003עיר הנדחת? אפילו דעלמא נמי\u0004 \u0005[אפילו\u0006 בעיר \u0005סתם גם כן],\u0006 שהרי לשיטה זו הלקוח בכסף מעשר שני שנטמא נקבר!","\u0003אלא לעולם\u0004 מדובר \u0003ב\u0004מעשר שני \u0003טהור\u0004 של עיר הנדחת ומעשר זה הובא לירושלים \u0003וכגון דנפול\u0004 \u0005[שנפלו]\u0006 \u0003מחיצות\u0004 העיר ירושלים אחר כך, \u0003וכ\u0004שיטת \u0003רבא\u0004, ש\u0003אמר רבא: מחיצה לאכול,\u0004 כלומר, הצורך בחומה סביב העיר ירושלים כדי להתיר בה אכילת מעשר הוא חובה \u0003דאורייתא\u0004 \u0005[שמן התורה],\u0006 ואולם מחיצה לענין \u0003לקלוט,\u0004 שמשעת כניסה לירושלים ייחשב המעשר כרכוש גבוה הוא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, \u0003וכי גזור רבנן\u0004 \u0005[וכאשר גזרו\u0006 זאת \u0005חכמים],\u0006 הרי זה רק \u0003כי אתנהו\u0004 \u0005[כאשר ישנה]\u0006 ה\u0003מחיצה,\u0004 ואולם \u0003כי ליתנהו\u0004 \u0005[כאשר אין]\u0006 \u0003מחיצה\u0004 — \u0003לא\u0004 גזרו, ונשאר המעשר בגדר שלל עיר הנדחת, ולא משום שהיתה בו קדושה אינו נשרף כשאר רכושה.","שנינו במשנה ש\u0003כתבי הקדש\u0004 שהיו בעיר הנדחת — \u0003יגנזו.\u0004 ומעירים: שיטת \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: כל עיר שיש בה אפילו מזוזה אחת\u0004 — \u0003אינה נעשית עיר הנדחת, שנאמר: \"ושרפת באש את העיר ואת כל שללה כליל\"\u0004 (דברים יג, יז) \u0003והיכא דאיכא\u0004 \u0005[והיכן שיש]\u0006 \u0003מזוזה לא אפשר\u0004 לשרוף הכל, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ד), שאסור להשמיד דבר שיש עליו שם שמים.","שנינו במשנה ש\u0003ר' שמעון אומר: אמר הקדוש ברוך הוא\u0004 וכו' ונחלקו ר' עקיבא ור' יוסי הגלילי אם מותר לנטוע גנות ופרדסים במקום עיר הנדחת. ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ב\u0004שיטת \u0003ר' אבין אמר ר' אילעא קמיפלגי\u0004 \u0005[חלוקים]\u0006 תנאים אלה, ש\u0003אמר ר' אבין אמר ר' אילעא: כל מקום שאתה מוצא כלל\u0004 בענין מסויים המנוסח בלשון \u0003\"עשה\", ופרט\u0004 באותו נושא שהיא בלשון \u0003\"לא תעשה\"\u0004 — \u0003אין דנין אותו בכלל ופרט\u0004 ללמוד מזה על זה, אלא רואים אותם כשתי הלכות נפרדות.","ואם כן נאמר כי \u0003דמר אית ליה\u0004 \u0005[שחכם זה,\u0006 ר' יוסי הגלילי, \u0005יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003ר' אבין,\u0004 שהוא מפרש \"והיתה תל עולם\" (דברים יג, יז) כמצות עשה מיוחדת, ו\"לא תבנה עוד\" (דברים יג, יז) — כלאו נוסף בענין זה. \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא, \u0005אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ר' אבין\u0004 וכן מפרש: \"והיתה תל עולם\" — כלל, \"לא תבנה עוד\" — פרט, ואין בכלל אלא מה שבפרט, על כן: לא תבנה עוד כמות שהיתה, אבל נעשית גנות ופרדסים.","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אית להו\u0004 \u0005[יש להם,\u0006 מקבלים הם\u0005]\u0006 את שיטת \u0003ר' אבין, והכא\u0004 \u0005[וכאן]\u0006 \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006ענין \u0005זה נחלקו]:\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוסי הגלילי, \u0005סבור]\u0006 כי \u0003\"עוד\" לגמרי משמע\u0004 \u0005[משמעו],\u0006 כלומר, אין המקום נבנה כלל. \u0003ומר סבר\u0004 \u0005[חכם זה,\u0006 ר' עקיבא, \u0005סבור]\u0006 כי \u0003\"עוד\"\u0004 — כוונתו ש\u0003לכמה שהיתה אינה נבנית, אבל נעשית היא גנות ופרדסים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003היו בה אילנות תלושין\u0004 — \u0003אסורין\u0004 משום שלל עיר הנדחת, היו \u0003מחוברין\u0004 לקרקע — \u0003מותרין,\u0004 אבל אילנות של \u0003עיר אחרת, בין תלושין בין מחוברין\u0004 — \u0003אסור.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"עיר אחרת\"\u0004 זו? \u0003אמר רב חסדא:\u0004 הכוונה היא ל\u0003יריחו, דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"והיתה העיר חרם\u0004 היא וכל אשר בה \u0003לה'... וישבע יהושע בעת ההיא לאמר ארור האיש לפני ה' אשר יקום ובנה את העיר הזאת את יריחו בבכרו ייסדנה\u0004 \u0003ובצעירו יציב דלתיה\"\u0004 (יהושע ו, יז. ויהושע ו כו).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 שבכלל איסור זה: \u0003לא\u0004 לבנות \u0003יריחו על שם עיר אחרת,\u0004 שאסור לבנותה שוב בשינוי שם, \u0003ולא\u0004 לבנות \u0003עיר אחרת על שם יריחו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנה חיאל בית האלי את יריחה באבירם בכרו יסדה ובשגוב צעירו הציב דלתיה\"\u0004 (מלכים א' טז, לד).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 אכן ממיתת \u0003אבירם בכורו\u0004 שהיה \u0003רשע לא היה לו ללמוד\u0004 עדיין שלא לבנות את יריחו, שיכול היה לתלות מיתתו ברשעותו, ואולם \u0003בשגוב צעירו\u0004 — \u0003היה לו ללמוד\u0004 כבר שקללת יהושע חלה עליו.","ותוהים: \u0003אבירם ושגוב מאי עבוד\u0004 \u0005[מה עשו]\u0006 שהם נקראים רשעים, ו\u0003מאי קאמר\u0004 \u0005[ומה אמר]\u0006 בענין זה עליהם? אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין: \u0003באבירם בכורו היה לו ללמוד לאותו רשע בשגוב צעירו.\u0004 כי \u0003ממשמע שנאמר: \"באבירם בכורו\" איני יודע ששגוב צעירו\u0004 הוא? אלא \u0003מה תלמוד לומר \"שגוב צעירו\"\u0004 — \u0003מלמד שהיה מקבר והולך\u0004 כל בניו \u0003מאבירם עד שגוב\u0004 והיה לו לחשוש שמא קללת יהושע גרמה לו.","מסופר: \u0003אחאב שושביניה הוה\u0004 \u0005[\u0006ידידו ו\u0005שושבינו\u0006 של חיאל \u0005היה]\u0006 \u0003אתא איהו\u0004 \u0005[בא הוא]\u0006 \u0003ואליהו למשאל בשלמא\u0004 \u0005[לשאול בשלומו]\u0006 \u0003בי טמיא\u0004 \u0005[בבית האבל].\u0006 \u0003יתיב וקאמר\u0004 \u0005[ישב\u0006 חיאל \u0005ואמר]:\u0006 \u0003דילמא כי מילט\u0004 \u0005[שמא כאשר קילל]\u0006 \u0003יהושע, הכי לט\u0004 \u0005[כך קילל]:\u0006 \u0003לא יריחו על שם עיר אחרת, ולא עיר אחרת על שם יריחו? אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליהו: אין\u0004 \u0005[כן]\u0006 כך היתה הקללה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחאב לאליהו: \u0003השתא לווטתא\u0004 \u0005[עכשיו קללתו]\u0006 של \u0003משה לא קא מקיימא\u0004 \u0005[אינה מתקיימת],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וסרתם ועבדתם\u0004 אלהים אחרים... \u0003וחרה אף ה' בכם ועצר את השמים\" וגו'\u0004 (דברים יא, טז–יז), \u0003וההוא גברא\u0004 \u0005[ואותו אדם]\u0006 אחאב \u0003אוקים ליה\u0004 \u0005[הקים לו]\u0006 \u0003עבודה זרה על כל תלם ותלם\u0004 שבארץ, \u0003ולא שביק ליה מיטרא דמיזל מיסגד ליה\u0004 \u0005[הניח לו הגשם שילך ויעבוד אותו],\u0006 שהרי היו גשמים רבים כל אותם ימים. ורצונך לומר כי \u0003לווטתא\u0004 \u0005[קללתו]\u0006 של \u0003יהושע תלמידיה מקיימא\u0004 \u0005[תלמידו מתקיימת]?\u0006 על כן נסמך מעשה זה לכאן.","\u0003מיד\u0004 — \u0003\"ויאמר אליהו התשבי מתשבי גלעד\u0004 אל אחאב \u0003חי ה' אלהי ישראל\u0004 אשר עמדתי לפניו \u0003אם יהיה\u0004 השנים האלה \u0003טל ומטר\u0004 כי אם לפי דברי\u0003\"\u0004 (מלכים א' יז, א). \u0003בעי רחמי\u0004 \u0005[בקש\u0006 אליהו \u0005רחמים]\u0006 \u0003והבו ליה אקלידא דמטרא\u0004 \u0005[נתנו לו מפתח המטר]\u0006 שלא ירד מטר אלא על פי דברו, \u0003וקם ואזל\u0004 \u0005[והלך].\u0006","נאמר שם: \u0003\"ויהי דבר ה' אליו לאמר. לך מזה ופנית לך קדמה ונסתרת בנחל כרית... והערבים מביאים לו לחם ובשר בבקר וגו' \"\u0004(מלכים א' יז ב. מלכים א' יז ג. מלכים א' יז ו). ושואלים: \u0003מהיכא\u0004 \u0005[מהיכן]\u0006 הביאו לו לחם ובשר? \u0003אמר ר' יהודה אמר רב: מבי טבחי\u0004 \u0005[מבית המטבחיים]\u0006 של \u0003אחאב.\u0004 עוד נאמר שם: \u0003\"ויהי מקץ ימים וייבש הנחל כי לא היה גשם בארץ\"\u0004 (מלכים א' יז ז), \u0003כיון דחזא דאיכא צערא בעלמא\u0004 \u0005[שראה\u0006 הקדוש ברוך הוא \u0005שיש צער בעולם],\u0006 ואין אליהו משגיח בדבר, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויהי דבר ה' אליו לאמר קום לך צרפתה\"\u0004 (מלכים א' יז ח —ט), כדי שיתגלגלו הענינים ולבסוף יוחזר לו מפתח הגשמים.","\u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי אחר הדברים האלה חלה בן האשה בעלת הבית\"\u0004 (מלכים א' יז יז), \u0003בעא רחמי למיתן ליה אקלידא\u0004 \u0005[בקש רחמים\u0006 לפני ה' \u0005ליתן לו\u0006 את \u0005המפתח]\u0006 של \u0003תחיית המתים. אמרי ליה\u0004 \u0005[אמרו לו\u0006 משמים\u0005]:\u0006 \u0003שלש מפתחות לא נמסרו\u0004 כרגיל \u0003לשליח,\u0004 והם מפתחות \u0003של חיה\u0004 (יולדת), \u0003ושל גשמים, ושל תחיית המתים.\u0004 ועכשיו שמפתח גשמים בידך ורוצה אתה מפתח תחיית המתים \u0003יאמרו: שתים ביד תלמיד ואחת ביד הרב! אייתי הא ושקיל האי\u0004 \u0005[הבא את זו,\u0006 של גשמים, \u0005וקח את זה],\u0006 שעל ידי בקשתו זו היה צריך לותר על שבועתו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לך הראה אל אחאב ואתנה מטר\"\u0004 (מלכים א' יח, א).","\u0003דרש ההוא גלילאה\u0004 \u0005[גלילי אחד]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא: משל\u0004 של \u0003אליהו למה הדבר דומה\u0004 — \u0003לגברא דטרקיה לגליה ואבדיה למפתחיה\u0004 \u0005[לאדם שסגר את דלתו ואבד את מפתחו],\u0006 שגם לאחר שויתר על שבועתו לא בא מיד המטר בגללו, אלא לפי דבר ה'.","\u0003דרש ר' יוסי בציפורי: אבא אליהו\u0004 כלומר, אליהו הנביא החשוב והחביב"],["\u0003קפדן הוה\u0004 \u0005[היה].\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003רגיל\u0004 אליהו \u0003למיתי גביה\u0004 \u0005[לבוא אליו]\u0006 ולהתגלות בכל יום לר' יוסי, \u0003איכסיה מיניה תלתא יומי\u0004 \u0005[נעלם ממנו שלושה ימים]\u0006 \u0003ולא אתא\u0004 \u0005[בא].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אתא מר\u0004 \u0005[בא אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 והלא \u0003\"קפדן\" קרית\u0004 \u0005[קראת]\u0006 \u0003לי! אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי לאליהו: \u0003הא דקמן, דקא קפיד מר\u0004 \u0005[הרי\u0006 זו \u0005לפנינו\u0006 דוגמא למה שאמרתי, \u0005שהרי הקפיד אדוני]\u0006 עלי בימים אלה.","שנינו במשנה על הכתוב \u0003\"ולא ידבק בידך מאומה מן החרם\"\u0004 (דברים יג, \u0003יח) —\u0004 \u0003כל זמן שרשעים בעולם חרון אף בעולם.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003רשעים\u0004 אלה שמדובר בהם כאן? \u0003אמר רב יוסף:\u0004 הם \u0003גנבי\u0004 \u0005[גנבים].\u0006 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רשע בא לעולם\u0004 — \u0003חרון בא לעולם, שנאמר: \"בבוא רשע בא גם בוז ועם קלון חרפה\"\u0004 (משלי יח, ג), \u0003רשע אבד מן העולם\u0004 — \u0003טובה באה לעולם, שנאמר: \"ובאבד רשעים רנה\"\u0004 (משלי יא, י). \u0003צדיק נפטר מן העולם\u0004 — \u0003רעה באה לעולם, שנאמר: \"הצדיק אבד ואין איש שם על לב ואנשי חסד נאספים באין מבין כי מפני הרעה נאסף הצדיק\"\u0004 (ישעיה נז, א). כש\u0003צדיק בא לעולם\u0004 — \u0003טובה באה לעולם\u0004 עמו, \u0003שנאמר\u0004 בנח: \u0003\"זה ינחמנו ממעשנו ומעצבון ידינו\"\u0004 (בראשית ה, כט).","",""]]};
